export const polar=(radius:number,angle:number)=>({x:Math.cos(angle*Math.PI/180)*radius,y:Math.sin(angle*Math.PI/180)*radius});
export function arcPath(radius:number,start:number,end:number){const a=polar(radius,start),b=polar(radius,end);return `M${a.x} ${a.y}A${radius} ${radius} 0 ${end-start>180?1:0} 1 ${b.x} ${b.y}`}
export function annularSector(index:number,count:number,outer:number,inner:number,gap=1.5){if(count===1)return `M${outer} 0A${outer} ${outer} 0 1 1 ${-outer} 0A${outer} ${outer} 0 1 1 ${outer} 0M${inner} 0A${inner} ${inner} 0 1 0 ${-inner} 0A${inner} ${inner} 0 1 0 ${inner} 0`;const mid=-90+index*360/count,start=mid-180/count+gap,end=mid+180/count-gap,a=polar(outer,start),b=polar(outer,end),c=polar(inner,end),d=polar(inner,start),large=end-start>180?1:0;return `M${a.x} ${a.y}A${outer} ${outer} 0 ${large} 1 ${b.x} ${b.y}L${c.x} ${c.y}A${inner} ${inner} 0 ${large} 0 ${d.x} ${d.y}Z`}
export function dialFraction(x:number,y:number){const angle=(Math.atan2(y,x)*180/Math.PI-135+360)%360;return angle<=270?angle/270:angle<315?1:0}
